using System.Collections.Generic; using UnityEngine; using UnityEngine.UI; using UnityEngine.SceneManagement; namespace DietCreature { /// <summary> /// 농장 씬 진입 시 농장(location=="farm") 생명체를 배치하고, /// 좌상단에 '농장 안 생물 수 N/최대수용' HUD, 하단에 생물 카드 바를 표시한다. /// 카드 클릭 → 생물 상세(이름/별명설정/태어난 날/성별) 팝업. /// </summary> public class FarmSpawner : MonoBehaviour { public GameObject creaturePrefab; public float bx = 3.8f; // 좌우 경계(대칭) public float topY = 7.3f; // 위쪽 경계 public float bottomY = -3.9f; // 아래쪽 경계(울타리 위로 겹쳐 보이지 않게 여유) private GameObject _canvas; private Font _font; private CreatureDetailPopup _detail; // 월드에 배치된 생물 GameObject 매핑(CreatureData 참조 → 월드 오브젝트). 성장 시 씬 리로드 없이 제자리 갱신용. private readonly Dictionary<CreatureData, GameObject> _worldCreatures = new Dictionary<CreatureData, GameObject>(); private void Start() { // 시너지 평가: 조건 충족 → 특수 생물 자연 발생 / 조건 해제 → 떠남 (아래 표시/배치에 즉시 반영) var synergy = SynergyManager.EvaluateFarm(); var creatures = GameState.CreaturesAt(CreatureData.LocFarm); _canvas = GameObject.Find("Canvas"); if (_canvas != null) { var anyText = _canvas.GetComponentInChildren<Text>(true); // 캔버스에 아직 Text가 없을 수 있으므로(스크립트 실행 순서) 테마 폰트로 폴백 _font = anyText != null ? anyText.font : UITheme.Body; _detail = _canvas.GetComponent<CreatureDetailPopup>(); if (_detail == null) _detail = _canvas.AddComponent<CreatureDetailPopup>(); _detail.font = _font; } BuildCountHud(creatures.Count); BuildCreatureBar(creatures); // 클릭 상호작용 감지기 if (GetComponent<FarmTouch>() == null) gameObject.AddComponent<FarmTouch>(); // 농장 식단 조합에 따른 날씨 연출(채식→햇살·무지개 / 육류→황금노을 / 인스턴트→비·천둥) if (GetComponent<FarmWeather>() == null) gameObject.AddComponent<FarmWeather>(); // 실제 기기 시계에 따른 밤낮 연출(해·달 아치 + 시간대 명암 틴트 + 밤 별). 날씨와 독립 오버레이. if (GetComponent<DayNightCycle>() == null) gameObject.AddComponent<DayNightCycle>(); // 관리자 모드 전용 시간 조절 슬라이더(밤낮 미리보기). 모드 꺼지면 숨김+실시간 복귀. if (GetComponent<DevTimeControl>() == null) gameObject.AddComponent<DevTimeControl>(); // 화면 비율에 맞춰 울타리를 가시 영역에 정렬(플립4 등 좁은 화면 좌우 울타리 사라짐 대응). if (GetComponent<FenceFit>() == null) gameObject.AddComponent<FenceFit>(); // 좁은 화면(플립4 등)에선 가시 가로폭이 좁아 bx(±3.8)를 벗어난 생물이 화면 밖에 놓인다. // 카메라 가시 반폭 안으로 좌우 경계를 클램프한다(FenceFit이 화면 변화 시 재보정). float effBx = bx; var mainCam = Camera.main; if (mainCam != null && mainCam.orthographic) effBx = Mathf.Min(bx, mainCam.orthographicSize * mainCam.aspect - 0.5f); // 월드에 스프라이트 배치(하이어라키 정리를 위해 빈 부모 아래로 모음) if (creaturePrefab != null) { var creatureRoot = new GameObject("CreatureRoot").transform; string[] emotes = { "heart", "note", "sparkle", "smile", "exclaim" }; var placed = new List<Vector2>(); // 스폰 시 서로 겹치지 않게 간격 확보용 for (int i = 0; i < creatures.Count; i++) { var data = creatures[i]; var c = Instantiate(creaturePrefab, creatureRoot); c.name = "Creature_" + (i + 1).ToString("00") + "_" + data.species; _worldCreatures[data] = c; // 성장 제자리 갱신용 매핑 c.transform.position = PickSpawnPos(effBx, bottomY, topY, placed); var def = CreatureCatalog.Get(data.species); float s = Random.Range(0.9f, 1.2f) * SpeciesScale(def); c.transform.localScale = new Vector3(s, s, 1f); var sr = c.GetComponent<SpriteRenderer>(); if (sr != null) { var sp = CreatureCatalog.GetSprite(data); // 진화 반영 if (sp != null) sr.sprite = sp; } var w = c.GetComponent<CreatureWander>(); if (w != null) { w.minX = -effBx; w.maxX = effBx; w.minY = bottomY; w.maxY = topY; // 정지형 종(스핑크스 등)은 배회하지 않고 생성 자리에 머문다. // DecorFx 벤치 섭외도 enabled 검사로 자동 제외된다. if (def != null && def.stationary) w.enabled = false; } // 밤이면 잠드는 상태 관리(CreatureInteract보다 먼저 부착 → Interact가 참조 확보) var slp = c.AddComponent<CreatureSleep>(); slp.species = data.species; slp.stage = data.stage; // 진화형이면 진화 수면 스프라이트 // 걷기 애니메이션: 걷기 프레임이 있는 종만 이동 중 프레임 순환. // 정지형(세계수 요정)은 움직이지 않으므로 제자리에서 계속 재생한다(주변 파티클 반짝임). var walk = CreatureCatalog.GetWalkFrames(data.species, data.stage); if (walk != null && walk.Length > 0) { var wanim = c.AddComponent<CreatureWalkAnim>(); wanim.frames = walk; wanim.alwaysPlay = def != null && def.stationary; if (wanim.alwaysPlay) wanim.frameDuration = 0.35f; // 걸음이 아니라 반짝임이라 느리게 } // 클릭 상호작용: 콜라이더 + 종별로 다른 반응/이모트 if (c.GetComponent<Collider2D>() == null) c.AddComponent<CircleCollider2D>().radius = 0.5f; int h = 0; foreach (char ch in data.species) h += ch; var ci = c.AddComponent<CreatureInteract>(); ci.motionVariant = h % 5; ci.emoteId = emotes[(h / 3) % emotes.Length]; } } // 시너지로 특수 생물이 등장/떠남 알림 팝업 (둘 다면 작별 팝업이 위에 겹쳐 먼저 보임) if (synergy.spawned != null && synergy.spawned.Count > 0) ShowSynergyPopup(synergy.spawned); if (synergy.departed != null && synergy.departed.Count > 0) ShowFarewellPopup(synergy.departed); // 농장 첫 방문 튜토리얼 if (_canvas != null) TutorialPopup.ShowOnce(_canvas.transform, _font, "farm", "농장", "부화시킨 생명체들이 여기서 자유롭게 지내요.
생물을 톡 누르면 반가워해요!

생물이 많을수록 골드도 더 많이 벌려요."); } /// <summary> /// 이미 배치된 생물들과 가장 멀리 떨어지는 후보를 고른다(최대 12회 샘플링, /// 최소 간격 1.6 확보되면 즉시 채택). 스폰 시점부터 생물이 서로 겹치지 않게 한다. /// </summary> private static Vector3 PickSpawnPos(float bx, float bottomY, float topY, List<Vector2> placed) { Vector2 best = Vector2.zero; float bestD = -1f; for (int t = 0; t < 12; t++) { var p = new Vector2(Random.Range(-bx, bx), Random.Range(bottomY, topY)); float d = float.MaxValue; foreach (var q in placed) d = Mathf.Min(d, Vector2.Distance(p, q)); if (d > bestD) { bestD = d; best = p; } if (bestD >= 2.0f) break; } placed.Add(best); return new Vector3(best.x, best.y, 0f); } // 특수(시크릿) 생물 자연 발생 알림 팝업. 먼지 몬스터는 경고 톤, 그 외는 축하 톤. private void ShowSynergyPopup(List<string> speciesIds) { if (_canvas == null) return; bool ominous = speciesIds.Contains("dust_monster"); var root = UIFactory.NewUI("SynergyPopup", _canvas.transform); UIFactory.Stretch(root); root.AddComponent<Image>().color = new Color(0f, 0f, 0f, 0.62f); root.AddComponent<Button>(); // 뒤 배경 클릭 흡수 root.AddComponent<Popup>().boxName = "Box"; var box = UIFactory.NewUI("Box", root.transform); UIFactory.Place(box, new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f), Vector2.zero, new Vector2(840f, 840f)); box.AddComponent<Image>().color = new Color(1f, 0.98f, 0.92f, 1f);

