using UnityEngine; namespace SewerRatClimb.CameraSystem { /// <summary> /// ParallaxLayer 디버그 전용 컴포넌트. /// ParallaxLayer가 붙은 오브젝트에 같이 붙이면 콘솔에 상세 로그를 출력합니다. /// 테스트 후 제거하세요. /// </summary> public sealed class ParallaxLayerDebug : MonoBehaviour { [Header("로그 필터 (초당 너무 많으면 여기서 조절)")] [Tooltip("이 값보다 큰 delta만 로그 출력 (0 = 매 프레임 전부)")] [SerializeField] private float logDeltaThreshold = 0.01f; [Tooltip("이 값보다 큰 배경 이동만 로그 출력")] [SerializeField] private float logBgMoveThreshold = 0.01f; private Transform cam; private Vector3 prevCamPos; private Vector3 prevBgPos; private int frameCount; private void Awake() { cam = Camera.main ? Camera.main.transform : null; } private void Start() { if (cam == null) { Debug.LogError("[ParallaxDebug] Camera.main 없음!", this); return; } prevCamPos = cam.position; prevBgPos = transform.position; Debug.Log($"[ParallaxDebug] 초기화
" + $" 배경 world pos : {transform.position}
" + $" 카메라 pos : {cam.position}
" + $" textureSizeY : (SpriteRenderer에서 읽음)
" + $" 오브젝트 : {gameObject.name}", this); } private void LateUpdate() { if (cam == null) return; frameCount++; Vector3 camDelta = cam.position - prevCamPos; Vector3 bgDelta = transform.position - prevBgPos; // FrozenByCamera / IsBlending 상태면 배경이 고정되는 게 정상 → 경고 억제 bool frozen = ParallaxLayer.FrozenByCamera || (Camera.main != null && Camera.main.TryGetComponent<Unity.Cinemachine.CinemachineBrain>(out var b) && b.IsBlending); // ── 큰 카메라 이동 감지 ────────────────────────────────── if (camDelta.magnitude > logDeltaThreshold) { string frozenTag = frozen ? " [FROZEN]" : ""; Debug.Log($"[ParallaxDebug] F{frameCount} 카메라 이동{frozenTag}
" + $" cam.prev : {prevCamPos}
" + $" cam.now : {cam.position}
" + $" camDelta : {camDelta} (magnitude={camDelta.magnitude:F3})
" + $" bg.now : {transform.position}", this); } // ── 배경 이동 감지 ──────────────────────────────────────── if (!frozen && bgDelta.magnitude > logBgMoveThreshold) { float expectedY = camDelta.y * GetParallaxFactorY(); float actualY = bgDelta.y; float errorY = actualY - expectedY; Debug.Log($"[ParallaxDebug] F{frameCount} 배경 이동
" + $" bg.prev : {prevBgPos}
" + $" bg.now : {transform.position}
" + $" bgDelta : {bgDelta}
" + $" 예상 이동(Y) : {expectedY:F4} 실제(Y): {actualY:F4} 오차: {errorY:F4}", this); } // ── 배경이 기대 위치와 많이 차이 날 때 경고 ────────────── // frozen 중에는 배경이 안 움직이는 게 정상이므로 스킵 if (!frozen) { float unexpectedBgX = bgDelta.x - camDelta.x * GetParallaxFactorX(); float unexpectedBgY = bgDelta.y - camDelta.y * GetParallaxFactorY(); if (Mathf.Abs(unexpectedBgX) > 0.5f || Mathf.Abs(unexpectedBgY) > 0.5f) { Debug.LogWarning($"[ParallaxDebug] ⚠ F{frameCount} 배경이 예상보다 많이 이동!
" + $" 초과 이동 X: {unexpectedBgX:F3} Y: {unexpectedBgY:F3}
" + $" → InfiniteScroll 점프이거나 외부에서 위치 변경 의심", this); } } prevCamPos = cam.position; prevBgPos = transform.position; } // ParallaxLayer의 factor를 리플렉션 없이 읽기 위한 헬퍼 // (SerializeField는 직접 접근 불가하므로 Inspector에서 같은 값을 수동 복사하거나 // ParallaxLayer에 프로퍼티를 추가해서 읽어도 됩니다) [Header("ParallaxLayer 와 같은 값으로 설정하세요")] [SerializeField] private float debugParallaxFactorX = 0.5f; [SerializeField] private float debugParallaxFactorY = 0.3f; private float GetParallaxFactorX() => debugParallaxFactorX; private float GetParallaxFactorY() => debugParallaxFactorY; } }
